-- 36: PRE-FLIGHT for the website migration 20261118100000_temporary_staff_links. Read-only.
-- One result set. Rows 1 to 4 must say ok = true (what the migration builds on is there, and none of its names is taken). Any later row is information only (it never blocks).
select * from (
  select 1 as n, 'the functions this builds on exist' as check_name,
         (to_regprocedure('public.invite_member(uuid, text, text, uuid, uuid, uuid, timestamptz, timestamptz, interval)') is not null and to_regprocedure('public.can_invite_role(uuid, text, uuid, uuid)') is not null and to_regprocedure('public.can_view_membership(uuid, uuid, uuid)') is not null and to_regprocedure('public.desk_log(text, text, uuid, jsonb)') is not null and to_regprocedure('public.resend_invitation(uuid, interval)') is not null and to_regprocedure('public.accept_invitation(text)') is not null and to_regprocedure('public.is_org_member(uuid, text[])') is not null) as ok,
         concat_ws(', ', case when to_regprocedure('public.invite_member(uuid, text, text, uuid, uuid, uuid, timestamptz, timestamptz, interval)') is null then 'public.invite_member missing' end, case when to_regprocedure('public.can_invite_role(uuid, text, uuid, uuid)') is null then 'public.can_invite_role missing' end, case when to_regprocedure('public.can_view_membership(uuid, uuid, uuid)') is null then 'public.can_view_membership missing' end, case when to_regprocedure('public.desk_log(text, text, uuid, jsonb)') is null then 'public.desk_log missing' end, case when to_regprocedure('public.resend_invitation(uuid, interval)') is null then 'public.resend_invitation missing' end, case when to_regprocedure('public.accept_invitation(text)') is null then 'public.accept_invitation missing' end, case when to_regprocedure('public.is_org_member(uuid, text[])') is null then 'public.is_org_member missing' end) as detail
  union all
  select 2, 'the tables and columns this builds on exist',
         (to_regclass('public.site_invitations') is not null and exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'site_invitations' and column_name = 'token_hash') and exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'site_invitations' and column_name = 'status') and exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'site_invitations' and column_name = 'expires_at') and exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'site_invitations' and column_name = 'accepted_by') and exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'site_invitations' and column_name = 'email') and exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'site_invitations' and column_name = 'org_id')),
         'site_invitations.accepted_by, site_invitations.email, site_invitations.expires_at, site_invitations.org_id, site_invitations.status, site_invitations.token_hash'
  union all
  select 3, 'none of the new names is taken (8 functions, 1 tables, 4 columns, 2 triggers)',
         (not exists (select 1 from pg_proc p where p.pronamespace = 'public'::regnamespace and p.proname = any (array['invite_temporary_staff', 'issue_invitation_code', 'verify_invitation_code', 'invitation_preview', 'request_invitation_renewal', 'list_invitation_extras', 'temporary_invitation_gate', 'invitation_new_link_resets'])) and to_regclass('public.site_invitation_codes') is null and not exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'site_invitations' and column_name = 'kind') and not exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'site_invitations' and column_name = 'identity_verified_at') and not exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'site_invitations' and column_name = 'renewal_requested_at') and not exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'site_invitations' and column_name = 'renewal_note') and not exists (select 1 from pg_trigger g where g.tgname = 'site_invitations_temporary_gate') and not exists (select 1 from pg_trigger g where g.tgname = 'site_invitations_new_link_resets')),
         concat_ws(', ', coalesce((select string_agg(p.proname, ', ') from pg_proc p where p.pronamespace = 'public'::regnamespace and p.proname = any (array['invite_temporary_staff', 'issue_invitation_code', 'verify_invitation_code', 'invitation_preview', 'request_invitation_renewal', 'list_invitation_extras', 'temporary_invitation_gate', 'invitation_new_link_resets'])), ''), case when to_regclass('public.site_invitation_codes') is not null then 'table site_invitation_codes exists' else '' end, case when exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'site_invitations' and column_name = 'kind') then 'site_invitations.kind exists' else '' end, case when exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'site_invitations' and column_name = 'identity_verified_at') then 'site_invitations.identity_verified_at exists' else '' end, case when exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'site_invitations' and column_name = 'renewal_requested_at') then 'site_invitations.renewal_requested_at exists' else '' end, case when exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'site_invitations' and column_name = 'renewal_note') then 'site_invitations.renewal_note exists' else '' end)
  union all
  select 4, 'the roles exist (the functions are granted to authenticated and service_role and taken from anon)',
         exists (select 1 from pg_roles where rolname = 'service_role') and exists (select 1 from pg_roles where rolname = 'authenticated') and exists (select 1 from pg_roles where rolname = 'anon'),
         'service_role, authenticated, anon'
  union all
  select 5, 'INFORMATION: invitations that exist now (every one becomes a permanent invitation: nothing about them changes)', true, (select count(*)::text from public.site_invitations where status = 'pending') || ' pending, ' || (select count(*)::text from public.site_invitations) || ' in all'
  union all
  select 6, 'INFORMATION: the e-mail function needs the RESEND_API_KEY secret and the service role key in the project (set them in the dashboard; this cannot read secrets)', true, 'check in the Supabase dashboard'
) r order by n;
